class Solution:
    def minDifference(self, nums, queries):
        len_quer = len(queries)
        n = len(nums)

        anums = [0] * n
        anums[:] = nums
        anums.sort()
        mindif = float("inf")
        for i in range(n - 1):
            if anums[i + 1] - anums[i] < mindif:
                mindif = anums[i + 1] - anums[i]

        min_range = []

        ans = [0] * len_quer

        for i in range(len_quer):
            temp = nums[queries[i][0]:queries[i][1] + 1]

            for k in range(len(min_range)):
                if queries[i][0] <= min_range[k][0] and queries[i][1] >= min_range[k][1]:
                    ans[i] = mindif
                    continue
            temp = list(set(temp))
            if len(temp) == 1:
                ans[i] = -1
                continue
            temp.sort()

            minabs = float("inf")
            len_temp = len(temp)
            for j in range(len_temp - 1):
                if temp[j + 1] - temp[j] == mindif:
                    minabs = mindif
                    min_range.append([queries[i][0], queries[i][1]])

                    break
                else:
                    minabs = min(minabs, temp[j + 1] - temp[j])

            ans[i] = minabs

        return ans


